def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    rich_pressure = 0.0
    urgent_opp = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
            if opp.get('budget', 0) > budget:
                rich_pressure += 1.0
            if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        return float(min(budget, 18.0))

    max_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    base = 16.0 + 18.0 * scarcity
    if supply <= 17:
        base += 10.0
    elif supply >= 22:
        base -= 5.0

    if hp <= 2:
        base += 32.0
    elif hp <= 4:
        base += 18.0

    if no_water_days >= 2:
        base += 28.0
    elif no_water_days >= 1:
        base += 12.0

    base += min(10.0, rich_pressure * 3.0)
    base += min(8.0, urgent_opp * 2.0)

    if max_prev >= 140.0:
        if hp > 4 and no_water_days == 0 and supply >= 20:
            base = min(base, 24.0)
        else:
            base = max(base, 58.0)
    elif max_prev >= 90.0:
        base = max(base, min(max_prev * 0.72, 74.0))
    elif max_prev > 0.0:
        base = max(base, min(max_prev + 2.0, 62.0))
    else:
        base = max(base, 26.0)

    if day >= 8:
        base += 8.0
    if day >= 9 and hp <= 4:
        base += 10.0

    reserve = 0.0
    if hp > 4 and no_water_days == 0:
        reserve = 35.0
    elif hp > 2:
        reserve = 20.0

    affordable = max(0.0, budget - reserve)
    if hp <= 2 or no_water_days >= 2:
        affordable = budget

    bid = min(base, affordable if affordable > 0 else budget)

    if bid < 0:
        bid = 0.0
    if hp <= 2 and bid < 45.0:
        bid = min(budget, 45.0)

    return float(min(budget, max(0.0, bid)))

